(function(){
'use strict';
const $=id=>document.getElementById(id),catalogKey='declic-library-v1',builtins=DEClic_BUILTINS;
let custom=[],storageIssue=false,deleteTarget=null,uid=0,recoveryRaw=null,builderDescription='',persistError='',selectedSubjectId=null;
function readCatalog(){
 const raw=localStorage.getItem(catalogKey);if(raw===null)return {quizzes:[],damaged:null};
 let parsed;try{parsed=JSON.parse(raw);}catch{return {quizzes:[],damaged:raw};}
 if(!Array.isArray(parsed))return {quizzes:[],damaged:raw};
 const quizzes=[],ids=new Set();let damaged=parsed.length>50;
 for(const q of parsed.slice(0,50)){
  try{if(!q||typeof q.id!=='string'||!/^custom-[a-zA-Z0-9_-]{1,100}$/.test(q.id)||ids.has(q.id))throw new Error();
   const normalized=QuizCatalog.normalizeQuiz(q);ids.add(q.id);quizzes.push({...normalized,id:q.id,storageKey:'declic-'+q.id+'-v1',symbol:normalized.title.slice(0,1).toUpperCase(),custom:true});
  }catch{damaged=true;}
 }
 return {quizzes,damaged:damaged?raw:null};
}
try{const saved=readCatalog();custom=saved.quizzes;recoveryRaw=saved.damaged;storageIssue=recoveryRaw!==null;}catch{storageIssue=true;}
const all=()=>[...builtins,...custom];
const searchable=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr');
function notify(message,error=false){for(const id of ['library-message','subject-message']){$(id).textContent=message;$(id).classList.toggle('error',error);}}
function persist(update){persistError='';try{
 const latest=readCatalog();
 const next=update(latest.quizzes);
 if(latest.damaged!==null){
  const backupKey=catalogKey+'-recovery';const previous=localStorage.getItem(backupKey);
  if(previous!==null&&previous!==latest.damaged)localStorage.setItem(backupKey+'-'+Date.now(),previous);
  localStorage.setItem(backupKey,latest.damaged);recoveryRaw=latest.damaged;
 }
 localStorage.setItem(catalogKey,JSON.stringify(next));custom=next;storageIssue=false;return true;
 }catch(error){persistError=error.message&&error.message.startsWith('Tu peux')?error.message:'Le navigateur ne permet pas d’enregistrer ce quiz. Aucune donnée existante n’a été remplacée. Libère de l’espace, puis réessaie.';notify(persistError,true);return false;}
}
function node(tag,className,text){const e=document.createElement(tag);if(className)e.className=className;if(text!==undefined)e.textContent=text;return e;}
function download(quiz){const blob=new Blob([JSON.stringify({title:quiz.quizTitle?subjectMeta(quiz).title+' · '+quiz.quizTitle:quiz.title,subjectTitle:subjectMeta(quiz).title,description:quiz.description,cards:quiz.cards},null,2)],{type:'application/json;charset=utf-8'});const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=quiz.title.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').toLowerCase()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Quiz exporté. Tu peux l’importer sur un autre appareil. La progression reste propre à ce navigateur.');}
function subjectMeta(quiz){const title=quiz.subjectTitle||quiz.title,normalized=searchable(title).trim();const match=builtins.find(q=>q.subjectId===quiz.subjectId||q.subjectId===normalized||searchable(q.subjectTitle||q.title).trim()===normalized);return match?{id:match.subjectId,title:match.subjectTitle,symbol:match.symbol}:{id:'personal:'+normalized,title,symbol:title[0]};}
function subjects(){const groups=new Map();for(const quiz of all()){const meta=subjectMeta(quiz);if(!groups.has(meta.id))groups.set(meta.id,{...meta,quizzes:[]});groups.get(meta.id).quizzes.push(quiz);}return [...groups.values()];}
function hideScreens(){for(const id of ['library-screen','subject-screen','quiz-screen','course-screen'])$(id).classList.add('hidden');$('course-pdf').removeAttribute('src');}
function progressElements(article,quiz){const mastered=DeclicQuiz.progress(quiz),pct=Math.round(mastered/quiz.cards.length*100),meter=node('div','subject-meter');meter.setAttribute('role','progressbar');meter.setAttribute('aria-label','Progression de '+(quiz.quizTitle||quiz.title));meter.setAttribute('aria-valuemin','0');meter.setAttribute('aria-valuemax','100');meter.setAttribute('aria-valuenow',String(pct));const fill=node('div');fill.style.width=pct+'%';meter.appendChild(fill);article.append(meter,node('p','subject-progress',mastered+' / '+quiz.cards.length+' réussies · '+pct+' %'));return mastered;}
function renderSubject(){const group=subjects().find(s=>s.id===selectedSubjectId);if(!group)return;$('subject-title').textContent=group.title;$('subject-description').textContent=group.quizzes.some(q=>q.variant==='essential')?'Choisis le cours complet ou concentre-toi sur les notions essentielles.':'Choisis le quiz que tu veux réviser.';$('subject-count').textContent=group.quizzes.length+' quiz disponible'+(group.quizzes.length>1?'s':'');const container=$('subject-quiz-list');container.replaceChildren();for(const quiz of group.quizzes){const article=node('article','subject-card quiz-card'+(quiz.variant==='essential'?' variant-essential':''));article.dataset.quizId=quiz.id;article.append(node('span','subject-kind',quiz.variant==='essential'?'NOTIONS ESSENTIELLES':quiz.variant==='complete'?'TOUT LE COURS':'QUIZ PERSONNEL'),node('h2','',quiz.quizTitle||quiz.title),node('p','subject-description',quiz.description),node('p','subject-meta',quiz.cards.length+' questions · '+new Set(quiz.cards.map(c=>c.chapter)).size+' chapitres'));const mastered=progressElements(article,quiz),actions=node('div','subject-actions'),start=node('button','btn primary start-quiz',mastered?'Continuer ↗':'Commencer ↗');start.type='button';start.setAttribute('aria-label','Réviser '+group.title+' · '+(quiz.quizTitle||quiz.title));start.onclick=()=>openQuiz(quiz.id);const exportBtn=node('button','text-btn export-quiz','Exporter');exportBtn.type='button';exportBtn.setAttribute('aria-label','Exporter '+quiz.title);exportBtn.onclick=()=>download(quiz);actions.append(start,exportBtn);if(quiz.custom){const del=node('button','text-btn delete-btn','Supprimer');del.type='button';del.setAttribute('aria-label','Supprimer '+quiz.title);del.onclick=()=>{deleteTarget=quiz;$('delete-name').textContent=quiz.title;$('delete-dialog').showModal();};actions.appendChild(del);}article.appendChild(actions);container.appendChild(article);}const withCourse=group.quizzes.find(q=>globalThis.DeclicCourses?.available(q));$('subject-course').classList.toggle('hidden',!withCourse);$('subject-course').onclick=()=>{if(withCourse)DeclicCourses.open(withCourse);};}
function renderLibrary(){const groups=subjects(),query=searchable($('quiz-search').value.trim());$('library-count').textContent=groups.length+' matière'+(groups.length>1?'s':'')+' · '+all().length+' quiz';const container=$('quiz-list');container.replaceChildren();let visible=0;for(const group of groups){if(!searchable(group.title).includes(query))continue;visible++;const article=node('article','subject-card');article.dataset.subjectId=group.id;const top=node('div','subject-top'),symbol=node('span','subject-symbol',group.symbol);symbol.setAttribute('aria-hidden','true');top.append(symbol,node('span','subject-kind',group.quizzes.some(q=>!q.custom)?'MATIÈRE':'PERSONNEL'));article.append(top,node('h2','',group.title),node('p','subject-description',group.quizzes.some(q=>q.variant==='essential')?'Tout le cours et un quiz consacré à l’essentiel.':'Retrouve les quiz de cette matière.'),node('p','subject-meta',group.quizzes.length+' quiz disponible'+(group.quizzes.length>1?'s':'')));for(const quiz of group.quizzes){const mastered=DeclicQuiz.progress(quiz),pct=Math.round(mastered/quiz.cards.length*100);article.appendChild(node('p','subject-progress summary-progress',(quiz.quizTitle||quiz.title)+' : '+mastered+' / '+quiz.cards.length+' · '+pct+' %'));}const start=node('button','btn primary choose-subject','Choisir un quiz ↗');start.type='button';start.setAttribute('aria-label','Voir les quiz de '+group.title);start.onclick=()=>showSubject(group.id);article.appendChild(start);article.onclick=event=>{if(!event.target.closest('button,a'))showSubject(group.id);};container.appendChild(article);}$('no-results').classList.toggle('hidden',visible!==0);if(!query){const add=node('button','add-subject');add.type='button';add.append(node('span','add-plus','+'),node('strong','','Une nouvelle matière'),node('span','','Crée une matière et ajoute ses quiz'));add.onclick=()=>openBuilder();container.appendChild(add);}const options=$('subject-options');options.replaceChildren();for(const group of groups){const option=node('option');option.value=group.title;options.appendChild(option);}if(!$('subject-screen').classList.contains('hidden')){if(groups.some(g=>g.id===selectedSubjectId))renderSubject();else showLibrary();}}
function showLibrary(){DeclicQuiz.leave();selectedSubjectId=null;hideScreens();$('library-screen').classList.remove('hidden');$('home-button').classList.add('hidden');document.title='Déclic · Mes matières';renderLibrary();$('library-title').focus();window.scrollTo({top:0,behavior:'smooth'});}
function showSubject(id){const group=subjects().find(s=>s.id===id);if(!group){showLibrary();return;}DeclicQuiz.leave();selectedSubjectId=id;hideScreens();$('subject-screen').classList.remove('hidden');$('home-button').classList.remove('hidden');$('home-button').textContent='← Mes matières';document.title='Déclic · '+group.title;renderSubject();$('subject-title').focus();window.scrollTo({top:0,behavior:'smooth'});}
function openQuiz(id){const quiz=all().find(q=>q.id===id);if(!quiz)return;selectedSubjectId=subjectMeta(quiz).id;hideScreens();$('quiz-screen').classList.remove('hidden');$('home-button').classList.remove('hidden');$('home-button').textContent='← Les quiz';DeclicQuiz.open(quiz);$('quiz-subject').focus();window.scrollTo({top:0,behavior:'smooth'});}
function addRow(card={}){const row=node('fieldset','question-row'),num=++uid;row.dataset.cardId=card.id||'';row._sources=card.sources||[];row._priority=card.priority===true;row.appendChild(node('legend','','Question '+($('question-rows').children.length+1)));
 for(const [name,label,type,value] of [['question','Question','textarea',card.question||''],['answer','Correction attendue','textarea',card.answer||''],['chapter','Chapitre (facultatif)','input',card.chapter||'']]){const field=node('div','builder-field'),l=node('label','',label),input=node(type);input.id='edit-'+name+'-'+num;input.dataset.field=name;input.value=value;if(type==='textarea'){input.rows=name==='question'?2:3;input.maxLength=name==='question'?10000:40000;}else{input.type='text';input.maxLength=150;}l.htmlFor=input.id;field.append(l,input);row.appendChild(field);}
 const remove=node('button','text-btn','Retirer cette question');remove.type='button';remove.onclick=()=>{row.remove();if(!$('question-rows').children.length)addRow();Array.from($('question-rows').children).forEach((r,i)=>r.querySelector('legend').textContent='Question '+(i+1));};row.appendChild(remove);$('question-rows').appendChild(row);return row;}
function openBuilder(data,subjectTitle){builderDescription=data?.description||'';$('builder-subject').value=subjectTitle||data?.subjectTitle||'';$('builder-title').value=data?.title||'';$('builder-error').textContent='';$('question-rows').replaceChildren();uid=0;for(const card of data?.cards||[{}])addRow(card);$('builder-dialog').showModal();$('builder-title').focus();}
function saveBuilder(e){e.preventDefault();if(!$('builder-dialog').open)return;try{const rows=Array.from($('question-rows').children).map(row=>({...Object.fromEntries(Array.from(row.querySelectorAll('[data-field]')).map(input=>[input.dataset.field,input.value])),...(row.dataset.cardId?{id:row.dataset.cardId}:{}),...(row._sources.length?{sources:row._sources}:{}),...(row._priority?{priority:true}:{})})).filter(c=>c.question.trim()||c.answer.trim());const parsed=QuizCatalog.normalizeQuiz({title:$('builder-title').value,subjectTitle:$('builder-subject').value.trim()||$('builder-title').value,...(builderDescription?{description:builderDescription}:{}),cards:rows});const id='custom-'+crypto.randomUUID(),quiz={...parsed,id,storageKey:'declic-'+id+'-v1',symbol:parsed.title[0].toUpperCase(),custom:true};if(!persist(latest=>{if(latest.length>=50)throw new Error('Tu peux ajouter jusqu’à 50 quiz personnels. Exporte puis retire un ancien quiz pour en ajouter un autre.');return [...latest,quiz];})){$('builder-error').textContent=persistError||'Enregistrement impossible : vérifie l’espace disponible dans ton navigateur.';return;}$('builder-dialog').close();$('quiz-search').value='';renderLibrary();showSubject(subjectMeta(quiz).id);notify('« '+quiz.title+' » a été ajouté à ta bibliothèque.');}catch(error){$('builder-error').textContent=error.message;}}
async function importFile(){const file=$('import-file').files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('Le fichier est trop volumineux (5 Mo maximum).');let data;try{data=JSON.parse(await file.text());}catch{throw new Error('Ce fichier ne contient pas un quiz JSON valide. Utilise un fichier exporté depuis Déclic.');}const quiz=QuizCatalog.normalizeQuiz(data,file.name.replace(/\.json$/i,''));openBuilder(quiz);}catch(error){notify(error.message,true);}finally{$('import-file').value='';}}
$('home-button').onclick=()=>{if(selectedSubjectId&&$('subject-screen').classList.contains('hidden'))showSubject(selectedSubjectId);else showLibrary();};$('subjects-back').onclick=showLibrary;$('subject-add-quiz').onclick=()=>openBuilder(undefined,subjects().find(s=>s.id===selectedSubjectId)?.title);$('add-quiz').onclick=()=>openBuilder();$('quiz-search').addEventListener('input',renderLibrary);$('import-quiz').onclick=()=>$('import-file').click();$('import-file').addEventListener('change',importFile);$('add-question').onclick=()=>{const row=addRow();row.scrollIntoView({behavior:'smooth',block:'nearest'});row.querySelector('textarea').focus();};$('builder-form').addEventListener('submit',saveBuilder);$('cancel-builder').onclick=()=>$('builder-dialog').close();$('cancel-delete').onclick=()=>$('delete-dialog').close();$('confirm-delete').onclick=()=>{if(deleteTarget&&persist(latest=>latest.filter(q=>q.id!==deleteTarget.id))){try{localStorage.removeItem(deleteTarget.storageKey);}catch{}$('delete-dialog').close();deleteTarget=null;renderLibrary();notify('Le quiz personnel a été supprimé.');}};
window.addEventListener('storage',event=>{if(event.key!==catalogKey)return;try{const latest=readCatalog();custom=latest.quizzes;recoveryRaw=latest.damaged;renderLibrary();notify('Ta bibliothèque a été mise à jour depuis un autre onglet.');}catch{notify('La bibliothèque est temporairement inaccessible. Tes quiz ouverts restent disponibles.',true);}});
window.addEventListener('declic:progress',()=>{if(!$('library-screen').classList.contains('hidden')||!$('subject-screen').classList.contains('hidden'))renderLibrary();});
renderLibrary();if(storageIssue)notify('Une sauvegarde est endommagée ou inaccessible. Les quiz récupérables sont affichés ; une copie sera conservée avant tout nouvel enregistrement.',true);
globalThis.DeclicLibrary={all,subjects,showSubject,currentSubjectId:()=>selectedSubjectId,openQuiz,showLibrary,renderLibrary,openBuilder};
})();
